    public BigDecimal totalItem() {
        return precoUnitario.multiply(BigDecimal.valueOf(quantidade));
    }

    public BigDecimal pesoTotalItem() {
        return pesoKg.multiply(BigDecimal.valueOf(quantidade));
    }
}

